// where even = tensor[.., :half], odd = tensor[.., half:]

template <typename scalar_t>
__global__ void apply_rope_kernel(scalar_t* __restrict__ t,
                                  const float* __restrict__ cos,
                                  const float* __restrict__ sin,
                                  int seq, int heads, int head_dim) {
  int half = head_dim >> 1;
  long total = (long)seq * heads * half;
  for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total;
       idx += (long)gridDim.x * blockDim.x) {
    int d = idx % half;
    long tmp = idx / half;
    int h = tmp % heads;
    int s = tmp / heads;
    (void)h;

    long base = ((long)s * heads + (idx / half % heads)) * head_dim;
    // recompute h cleanly
    int hh = (int)((idx / half) % heads);
    base = ((long)s * heads + hh) * head_dim;

    long even_i = base + d;
    long odd_i = base + half + d;

    float c = cos[(long)s * half + d];
    float sn = sin[(long)s * half + d];

    float even = to_float(t[even_i]);
    float odd = to_float(t[odd_i]);

    t[even_i] = from_float<scalar_t>(even * c - odd * sn);
    t[odd_i] = from_float<scalar_t>(even * sn + odd * c);
  }
}

// -------------------- silu and mul --------------------
// out[r, i] = silu(gate_up[r, i]) * gate_up[r, hidden + i]
// silu(x) = x * sigmoid(x), computed in float32

template <typename scalar_t>
__global__ void silu_and_mul_kernel(const scalar_t* __restrict__ gate_up,
                                    scalar_t* __restrict__ out,
                                    int rows, int hidden) {
  long total = (long)rows * hidden;
  int two_h = hidden * 2;
  for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total;
       idx += (long)gridDim.x * blockDim.x) {
    int col = idx % hidden;
    int row = idx / hidden;
    const scalar_t* gu_row = gate_up + (long)row * two_h;
    float g = to_float(gu_row[col]);
    float u = to_float(gu_row[hidden + col]);
    float silu = g / (1.0f + __expf(-g));
    out[idx] = from_float<scalar_t>(silu * u);
  }
}

// -------------------- launch dispatch --------------------

int rmsnorm_block_size(int N) {
  int bs = 32;
  while (bs < N && bs < 1024) bs <<= 1;
  if (bs > 1024) bs = 1024;
  if (bs < 32) bs = 32;
  return bs;
}

}  // namespace

// -------------------- C++ entry points --------------------

torch::Tensor rmsnorm(torch::Tensor input, torch::Tensor weight, double eps) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(input.dim() == 2, "input must be 2D");
  auto in = input.contiguous();
  auto w = weight.contiguous();
  auto out = torch::empty_like(in);
  int M = in.size(0);
  int N = in.size(1);
  int bs = rmsnorm_block_size(N);
  auto stream = at::cuda::getCurrentCUDAStream();

  AT_DISPATCH_REDUCED_FLOATING_TYPES(in.scalar_type(), "rmsnorm", [&] {
    using ct = std::conditional<std::is_same<scalar_t, at::BFloat16>::value,
                                __nv_bfloat16, __half>::type;
    rmsnorm_kernel<ct><<<M, bs, 0, stream>>>(
        reinterpret_cast<const ct*>(in.data_ptr<scalar_t>()),
        reinterpret_cast<const ct*>(w.data_ptr<scalar_t>()),
        reinterpret_cast<ct*>(out.data_ptr<scalar_t>()), N, (float)eps);
  });
  return out;
}

void fused_add_rmsnorm_(torch::Tensor input, torch::Tensor residual,
                        torch::Tensor weight, double eps) {
  TORCH_CHECK(input.is_cuda() && residual.is_cuda(), "must be CUDA");
  TORCH_CHECK(input.dim() == 2, "input must be 2D");
  auto w = weight.contiguous();
  int M = input.size(0);
  int N = input.size(1);
  int bs = rmsnorm_block_size(N);
  auto stream = at::cuda::getCurrentCUDAStream();

  AT_DISPATCH_REDUCED_FLOATING_TYPES(input.scalar_type(), "fused_add_rmsnorm_", [&] {
    using ct = std::conditional<std::is_same<scalar_t, at::BFloat16>::value,
                                __nv_bfloat16, __half>::type;
    fused_add_rmsnorm_kernel<ct><<<M, bs, 0, stream>>>(
        reinterpret_cast<ct*>(input.data_ptr<scalar_t>()),
        reinterpret_cast<ct*>(residual.data_ptr<scalar_t>()),
        reinterpret_cast<const ct*>(w.data_ptr<scalar_t>()), N, (float)eps);
  });
}

void apply_rope_(torch::Tensor q, torch::Tensor k, torch::Tensor cos,
                 torch::Tensor sin) {
  TORCH_CHECK(q.is_cuda() && k.is_cuda(), "must be CUDA");
  TORCH_CHECK(q.dim() == 4 && k.dim() == 4, "q,k must be 4D");
  auto c = cos.contiguous().to(torch::kFloat32);
  auto s = sin.contiguous().to(torch::kFloat32);
  auto stream = at::cuda::getCurrentCUDAStream();

  int seq = q.size(1);
  int head_dim = q.size(3);

  auto launch = [&](torch::Tensor t) {
    int heads = t.size(2);
    long total = (long)seq * heads * (head_dim / 2);
    int bs = 256;
    int grid = (int)((total + bs - 1) / bs);
    if (grid > 65535) grid = 65535;
    AT_DISPATCH_REDUCED_FLOATING_TYPES(t.scalar_type(), "apply_rope_", [&] {
      using ct = std::conditional<std::is_same<scalar_t, at::BFloat16>::value,
                                  __nv_bfloat16, __half>::type;
      apply_rope_kernel<ct><<<grid, bs, 0, stream>>>(
          reinterpret_cast<ct*>(t.data_ptr<scalar_t>()),
          c.data_ptr<float>(), s.data_ptr<float>(), seq, heads, head_dim);
    });
  };
  launch(q);
  launch(k);
}

torch::Tensor silu_and_mul(torch::Tensor gate_up, torch::Tensor out) {
  TORCH_CHECK(gate_up.is_cuda(), "must be CUDA");
  TORCH_CHECK(gate_up.dim() == 2, "gate_up must be 2D");
  auto gu = gate_up.contiguous();
  int rows = gu.size(0);
  int hidden = gu.size(1) / 2;
  long total = (long)rows * hidden;
  int bs = 256;
  int grid = (int)((total + bs - 1) / bs);
  if (grid > 65535) grid = 65535;
  auto stream = at::cuda::getCurrentCUDAStream();

  AT_DISPATCH_REDUCED_FLOATING_TYPES(gu.scalar_type(), "silu_and_mul", [&] {
    using ct = std::conditional<std::is_same<scalar_t, at::BFloat16>::value,
                                __nv_bfloat16, __half>::type;
    silu_and_mul_kernel<ct><<<grid, bs, 0, stream>>>(
        reinterpret_cast<const ct*>(gu.data_ptr<scalar_t>()),
        reinterpret_cast<ct*>(out.data_ptr<scalar_t>()), rows, hidden);
  });
  return out;
}

