  m.def("rmsnorm", &rmsnorm, "RMSNorm");
  m.def("fused_add_rmsnorm_", &fused_add_rmsnorm_, "Fused add + RMSNorm (in-place)");
  m.def("apply_rope_", &apply_rope_, "Apply RoPE in-place");
  m.def("silu_and_mul", &silu_and_mul, "SiLU and mul");
}

