// Custom CUDA kernels for the DeepSeek-style inference block.
//
// This translation unit deliberately avoids including <torch/extension.h>
// (which pulls in heavy ATen template headers that fail to compile under nvcc
// with newer host GCC). It exposes plain pointer-based launchers; the Torch /
// pybind glue lives in block_kernels.cpp.
//
// All accumulation is done in float32 to match the PyTorch reference math.

#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cstdint>

#include "block_kernels.h"

namespace {

// -------------------- type helpers --------------------

template <typename scalar_t>
__device__ __forceinline__ float to_float(scalar_t v) {
  return static_cast<float>(v);
}
template <>
__device__ __forceinline__ float to_float<__nv_bfloat16>(__nv_bfloat16 v) {
  return __bfloat162float(v);
}
template <>
__device__ __forceinline__ float to_float<__half>(__half v) {
  return __half2float(v);
}

template <typename scalar_t>
__device__ __forceinline__ scalar_t from_float(float v) {
  return static_cast<scalar_t>(v);
}
template <>
__device__ __forceinline__ __nv_bfloat16 from_float<__nv_bfloat16>(float v) {
  return __float2bfloat16(v);
}
template <>
__device__ __forceinline__ __half from_float<__half>(float v) {
  return __float2half(v);
}

// -------------------- warp / block reduction --------------------

__device__ __forceinline__ float warp_reduce_sum(float v) {
#pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    v += __shfl_down_sync(0xffffffffu, v, offset);
  }
  return v;
}

// One block per row. blockDim.x is a multiple of 32, up to 1024.
__device__ __forceinline__ float block_reduce_sum(float v, float* shared) {
  int lane = threadIdx.x & 31;
  int wid = threadIdx.x >> 5;
  v = warp_reduce_sum(v);
  if (lane == 0) shared[wid] = v;
  __syncthreads();
  int num_warps = (blockDim.x + 31) >> 5;
  v = (threadIdx.x < num_warps) ? shared[lane] : 0.0f;
  if (wid == 0) v = warp_reduce_sum(v);
  return v;
}

// -------------------- rmsnorm --------------------

template <typename scalar_t>
__global__ void rmsnorm_kernel(const scalar_t* __restrict__ input,
                               const scalar_t* __restrict__ weight,
                               scalar_t* __restrict__ out,
                               int N, float eps) {
  int row = blockIdx.x;
  const scalar_t* in_row = input + (long)row * N;
  scalar_t* out_row = out + (long)row * N;

  __shared__ float shared[32];

  float local = 0.0f;
  for (int i = threadIdx.x; i < N; i += blockDim.x) {
    float x = to_float(in_row[i]);
    local += x * x;
  }
  float ssum = block_reduce_sum(local, shared);
  __shared__ float inv_rms;
  if (threadIdx.x == 0) {
    inv_rms = rsqrtf(ssum / (float)N + eps);
  }
  __syncthreads();
  float r = inv_rms;
  for (int i = threadIdx.x; i < N; i += blockDim.x) {
    float x = to_float(in_row[i]);
    float w = to_float(weight[i]);
    out_row[i] = from_float<scalar_t>(x * r * w);
  }
}

// -------------------- fused add + rmsnorm (in-place) --------------------
// residual += input; input = rmsnorm(residual, weight)

template <typename scalar_t>
__global__ void fused_add_rmsnorm_kernel(scalar_t* __restrict__ input,
                                         scalar_t* __restrict__ residual,
                                         const scalar_t* __restrict__ weight,
                                         int N, float eps) {
  int row = blockIdx.x;
  scalar_t* in_row = input + (long)row * N;
  scalar_t* res_row = residual + (long)row * N;

  __shared__ float shared[32];

  float local = 0.0f;
  for (int i = threadIdx.x; i < N; i += blockDim.x) {
    float s = to_float(res_row[i]) + to_float(in_row[i]);
    res_row[i] = from_float<scalar_t>(s);
    local += s * s;
  }
  float ssum = block_reduce_sum(local, shared);
  __shared__ float inv_rms;
  if (threadIdx.x == 0) {
    inv_rms = rsqrtf(ssum / (float)N + eps);
  }
  __syncthreads();
  float r = inv_rms;
  for (int i = threadIdx.x; i < N; i += blockDim.x) {
    float s = to_float(res_row[i]);
    float w = to_float(weight[i]);
    in_row[i] = from_float<scalar_t>(s * r * w);
  }
}

// -------------------- apply rope (in-place, half-split) --------------------
// tensor shape: (1, seq, heads, head_dim); cos/sin shape: (seq, head_dim/2)
//   out[.. , :half]  = even * cos - odd * sin
//   out[.. , half:]  = even * sin + odd * cos
// where even = tensor[.., :half], odd = tensor[.., half:]

template <typename scalar_t>
__global__ void apply_rope_kernel(scalar_t* __restrict__ t,
                                  const float* __restrict__ cos,
                                  const float* __restrict__ sin,
                                  int seq, int heads, int head_dim) {
  int half = head_dim >> 1;
  long total = (long)seq * heads * half;
  for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total;
       idx += (long)gridDim.x * blockDim.x) {
    int d = idx % half;
    long tmp = idx / half;
    int h = (int)(tmp % heads);
    int s = (int)(tmp / heads);

    long base = ((long)s * heads + h) * head_dim;
    long even_i = base + d;
    long odd_i = base + half + d;

    float c = cos[(long)s * half + d];
    float sn = sin[(long)s * half + d];

    float even = to_float(t[even_i]);
    float odd = to_float(t[odd_i]);

    t[even_i] = from_float<scalar_t>(even * c - odd * sn);
    t[odd_i] = from_float<scalar_t>(even * sn + odd * c);
  }
}

// -------------------- silu and mul --------------------
// out[r, i] = silu(gate_up[r, i]) * gate_up[r, hidden + i]
// silu(x) = x * sigmoid(x), computed in float32

template <typename scalar_t>
__global__ void silu_and_mul_kernel(const scalar_t* __restrict__ gate_up,
                                    scalar_t* __restrict__ out,
                                    int rows, int hidden) {
  long total = (long)rows * hidden;
  int two_h = hidden * 2;
  for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total;
       idx += (long)gridDim.x * blockDim.x) {
    int col = idx % hidden;
    int row = idx / hidden;
    const scalar_t* gu_row = gate_up + (long)row * two_h;
    float g = to_float(gu_row[col]);
    float u = to_float(gu_row[hidden + col]);
    float silu = g / (1.0f + __expf(-g));
    out[idx] = from_float<scalar_t>(silu * u);
  }
}

int rmsnorm_block_size(int N) {
  int bs = 32;
  while (bs < N && bs < 1024) bs <<= 1;
  if (bs > 1024) bs = 1024;
  if (bs < 32) bs = 32;
  return bs;
}

}  // namespace

// -------------------- pointer-based launchers --------------------

template <typename ct>
static void launch_rmsnorm(const void* in, const void* w, void* out, int M,
                           int N, float eps, cudaStream_t stream) {
  int bs = rmsnorm_block_size(N);
  rmsnorm_kernel<ct><<<M, bs, 0, stream>>>(
      reinterpret_cast<const ct*>(in), reinterpret_cast<const ct*>(w),
      reinterpret_cast<ct*>(out), N, eps);
}

void cfb_rmsnorm(const void* in, const void* w, void* out, int M, int N,
                 float eps, int is_bf16, cudaStream_t stream) {
  if (is_bf16)
    launch_rmsnorm<__nv_bfloat16>(in, w, out, M, N, eps, stream);
  else
    launch_rmsnorm<__half>(in, w, out, M, N, eps, stream);
}

template <typename ct>
static void launch_fused(void* in, void* res, const void* w, int M, int N,
                         float eps, cudaStream_t stream) {
  int bs = rmsnorm_block_size(N);
  fused_add_rmsnorm_kernel<ct><<<M, bs, 0, stream>>>(
      reinterpret_cast<ct*>(in), reinterpret_cast<ct*>(res),
      reinterpret_cast<const ct*>(w), N, eps);
}

void cfb_fused_add_rmsnorm(void* in, void* res, const void* w, int M, int N,
                           float eps, int is_bf16, cudaStream_t stream) {
  if (is_bf16)
    launch_fused<__nv_bfloat16>(in, res, w, M, N, eps, stream);
  else
    launch_fused<__half>(in, res, w, M, N, eps, stream);
}

template <typename ct>
static void launch_rope(void* t, const float* c, const float* s, int seq,
                        int heads, int head_dim, cudaStream_t stream) {
  long total = (long)seq * heads * (head_dim / 2);
  int bs = 256;
  int grid = (int)((total + bs - 1) / bs);
  if (grid > 65535) grid = 65535;
  if (grid < 1) grid = 1;
  apply_rope_kernel<ct><<<grid, bs, 0, stream>>>(
      reinterpret_cast<ct*>(t), c, s, seq, heads, head_dim);
}

void cfb_apply_rope(void* t, const float* c, const float* s, int seq,
                    int heads, int head_dim, int is_bf16,
                    cudaStream_t stream) {
  if (is_bf16)
    launch_rope<__nv_bfloat16>(t, c, s, seq, heads, head_dim, stream);
  else
    launch_rope<__half>(t, c, s, seq, heads, head_dim, stream);
}

template <typename ct>
static void launch_silu(const void* gu, void* out, int rows, int hidden,
                        cudaStream_t stream) {
  long total = (long)rows * hidden;
  int bs = 256;
  int grid = (int)((total + bs - 1) / bs);
  if (grid > 65535) grid = 65535;
  if (grid < 1) grid = 1;
  silu_and_mul_kernel<ct><<<grid, bs, 0, stream>>>(
      reinterpret_cast<const ct*>(gu), reinterpret_cast<ct*>(out), rows,
      hidden);
}

void cfb_silu_and_mul(const void* gu, void* out, int rows, int hidden,
                      int is_bf16, cudaStream_t stream) {
  if (is_bf16)
    launch_silu<__nv_bfloat16>(gu, out, rows, hidden, stream);
  else
    launch_silu<__half>(gu, out, rows, hidden, stream);
}

