// Torch / pybind glue for the DeepSeek inference-block CUDA kernels.
// The kernels themselves live in block_kernels.cu; this file is compiled by the
// host C++ compiler, which handles <torch/extension.h> cleanly.

#include <torch/extension.h>
#include <c10/cuda/CUDAStream.h>

#include "block_kernels.h"

static inline int is_bf16_of(const torch::Tensor& t) {
  if (t.scalar_type() == torch::kBFloat16) return 1;
  TORCH_CHECK(t.scalar_type() == torch::kHalf,
              "only bfloat16 and float16 are supported");
  return 0;
}

torch::Tensor rmsnorm(torch::Tensor input, torch::Tensor weight, double eps) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(input.dim() == 2, "input must be 2D");
  auto in = input.contiguous();
  auto w = weight.contiguous();
  auto out = torch::empty_like(in);
  int M = in.size(0);
  int N = in.size(1);
  auto stream = c10::cuda::getCurrentCUDAStream();
  cfb_rmsnorm(in.data_ptr(), w.data_ptr(), out.data_ptr(), M, N, (float)eps,
              is_bf16_of(in), stream.stream());
  return out;
}

void fused_add_rmsnorm_(torch::Tensor input, torch::Tensor residual,
                        torch::Tensor weight, double eps) {
  TORCH_CHECK(input.is_cuda() && residual.is_cuda(), "must be CUDA");
  TORCH_CHECK(input.dim() == 2, "input must be 2D");
  TORCH_CHECK(input.is_contiguous() && residual.is_contiguous(),
              "input/residual must be contiguous");
  auto w = weight.contiguous();
  int M = input.size(0);
  int N = input.size(1);
  auto stream = c10::cuda::getCurrentCUDAStream();
  cfb_fused_add_rmsnorm(input.data_ptr(), residual.data_ptr(), w.data_ptr(), M,
                        N, (float)eps, is_bf16_of(input), stream.stream());
}

void apply_rope_(torch::Tensor q, torch::Tensor k, torch::Tensor cos,
                 torch::Tensor sin) {
  TORCH_CHECK(q.is_cuda() && k.is_cuda(), "must be CUDA");
  TORCH_CHECK(q.dim() == 4 && k.dim() == 4, "q,k must be 4D");
  TORCH_CHECK(q.is_contiguous() && k.is_contiguous(), "q,k must be contiguous");
  auto c = cos.contiguous().to(torch::kFloat32);
  auto s = sin.contiguous().to(torch::kFloat32);
  auto stream = c10::cuda::getCurrentCUDAStream();

  int seq = q.size(1);
  int head_dim = q.size(3);

  int q_heads = q.size(2);
  int k_heads = k.size(2);
  cfb_apply_rope(q.data_ptr(), c.data_ptr<float>(), s.data_ptr<float>(), seq,
                 q_heads, head_dim, is_bf16_of(q), stream.stream());
  cfb_apply_rope(k.data_ptr(), c.data_ptr<float>(), s.data_ptr<float>(), seq,
                 k_heads, head_dim, is_bf16_of(k), stream.stream());
}

torch::Tensor silu_and_mul(torch::Tensor gate_up, torch::Tensor out) {
  TORCH_CHECK(gate_up.is_cuda(), "must be CUDA");
  TORCH_CHECK(gate_up.dim() == 2, "gate_up must be 2D");
  auto gu = gate_up.contiguous();
  int rows = gu.size(0);
  int hidden = gu.size(1) / 2;
  auto stream = c10::cuda::getCurrentCUDAStream();
  cfb_silu_and_mul(gu.data_ptr(), out.data_ptr(), rows, hidden, is_bf16_of(gu),
                   stream.stream());
  return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("rmsnorm", &rmsnorm, "RMSNorm");
  m.def("fused_add_rmsnorm_", &fused_add_rmsnorm_,
        "Fused add + RMSNorm (in-place)");
  m.def("apply_rope_", &apply_rope_, "Apply RoPE in-place");
  m.def("silu_and_mul", &silu_and_mul, "SiLU and mul");
}

